/***************************************************************************************************** 
 *
 * Design a data structure that supports all following operations in average O(1) time.
 * 
 * 	insert(val): Inserts an item val to the set if not already present.
 * 	remove(val): Removes an item val from the set if present.
 * 	getRandom: Returns a random element from current set of elements (it's guaranteed that at 
 * least one element exists when this method is called). Each element must have the same probability 
 * of being returned.
 * 
 * Example:
 * 
 * // Init an empty set.
 * RandomizedSet randomSet = new RandomizedSet();
 * 
 * // Inserts 1 to the set. Returns true as 1 was inserted successfully.
 * randomSet.insert(1);
 * 
 * // Returns false as 2 does not exist in the set.
 * randomSet.remove(2);
 * 
 * // Inserts 2 to the set, returns true. Set now contains [1,2].
 * randomSet.insert(2);
 * 
 * // getRandom should return either 1 or 2 randomly.
 * randomSet.getRandom();
 * 
 * // Removes 1 from the set, returns true. Set now contains [2].
 * randomSet.remove(1);
 * 
 * // 2 was already in the set, so return false.
 * randomSet.insert(2);
 * 
 * // Since 2 is the only number in the set, getRandom always return 2.
 * randomSet.getRandom();
 ******************************************************************************************************/

class RandomizedSet {
    Map<Integer, Integer> map;
    List<Integer> list;
    Random random;

    /** Initialize your data structure here. */
    public RandomizedSet() {
        // key: val; value: index in array list
        map = new HashMap<Integer, Integer>();
        list = new ArrayList<Integer>();
        random = new Random();
    }

    /** Inserts a value to the set. Returns true if the set did not already contain the specified element. */
    public boolean insert(int val) {
        if (map.containsKey(val)) {
            return false;
        }

        list.add(val);
        map.put(val, list.size() - 1);
        return true;
    }

    /** Removes a value from the set. Returns true if the set contained the specified element. */
    public boolean remove(int val) {
        var index = (Integer) map.getOrDefault(val, -1);
        if (index == -1) {
            return false;
        }

        // 先 swap 再 remove，因为有可能只有 1 个元素
        var last = list.size() - 1;
        var tmp = list.get(index);
        list.set(index, list.get(last));
        list.set(last, tmp);
        map.put(list.get(index), index);

        list.remove(list.size() - 1);
        map.remove(val);
        return true;
    }

    /** Get a random element from the set. */
    public int getRandom() {
        var index = random.nextInt(list.size());
        return list.get(index);
    }
}

